    const persist = () => { storage.setItem(STORAGE_KEY, JSON.stringify(state.cart)); storage.setItem(THEME_KEY, state.dark ? 'dark' : 'light'); };

    function hexToRgb(hex) {
      const h = String(hex).replace('#','');
      return [parseInt(h.slice(0,2),16)||0, parseInt(h.slice(2,4),16)||0, parseInt(h.slice(4,6),16)||0];
    }
    function rgbToHex(r,g,b) { return '#' + [r,g,b].map(v => Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join(''); }
    function solidColor(hex) { return String(hex || '#ffffff'); }
    function blendedColor() {
      const total = state.mixer.reduce((a,c)=>a + Math.max(0,Number(c.weight)||0),0);
      if (!total) return '#ffffff';
      let rgb=[0,0,0];
      state.mixer.forEach(c => { const x=hexToRgb(c.hex), w=(Number(c.weight)||0)/total; rgb=rgb.map((v,i)=>v+x[i]*w); });
      return rgbToHex(...rgb);
    }
    function closestMatch(hex) {
      const rgb=hexToRgb(hex); let best=SHADES[0], dist=Infinity;
      SHADES.forEach(s => { const d=Math.hypot(rgb[0]-s.r,rgb[1]-s.g,rgb[2]-s.b); if(d<dist){dist=d;best=s;} });
      return { shade:best, pct:Math.max(0,Math.round(100-(dist/441)*100)) };
    }
    function addToCart(product, shade, size, finishType) {
      const color = noColor(product) ? { code:'—', name:'Standard', hex:'#8B7355' } : shade;
      const id = [product.id,size.label,color.code,finishType || product.name].join('-');
      const existing = state.cart.find(i => i.id === id);
      if (existing) existing.quantity += 1;
      else state.cart.push({ id, productId:product.id, productName:product.name, productImage:product.image, sizeLabel:size.label, sizeVolume:size.volume, price:size.price, bsCode:color.code, colorName:color.name, colorHex:color.hex, finishType:finishType || product.name, quantity:1 });
      persist(); state.cartOpen=true; render();
    }
    function cartSubtotal(){ return state.cart.reduce((t,i)=>t+i.price*i.quantity,0); }
    function updateQty(id, delta){ const item=state.cart.find(i=>i.id===id); if(!item)return; item.quantity+=delta; if(item.quantity<=0)state.cart=state.cart.filter(i=>i.id!==id); persist(); render(); }
    function removeCart(id){ state.cart=state.cart.filter(i=>i.id!==id); persist(); render(); }
    function checkoutWhatsApp(){
      let text='APEX COATING EAST AFRICA LTD\nORDER REQUEST\n\n';
      state.cart.forEach((i,n)=>{ text += `${n+1}. ${i.productName}\nShade: ${i.colorName} (${i.bsCode})\nFinish: ${i.finishType}\nSize: ${i.sizeVolume}\nQty: ${i.quantity}\nSubtotal: ${money(i.price*i.quantity)}\n\n`; });
      text += `ORDER TOTAL: ${money(cartSubtotal())}\nPlease confirm availability, pricing, and fulfilment terms directly with our team.`;
      window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(text)}`,'_blank');
    }
    function emailOrder(){
      let body='Dear Apex Coating Team,\n\nI would like to place the following order:\n\n';
      state.cart.forEach((i,n)=> body += `${n+1}. ${i.productName}\nShade: ${i.colorName} (${i.bsCode})\nFinish: ${i.finishType}\nSize: ${i.sizeVolume}\nQty: ${i.quantity}\nPrice: ${money(i.price*i.quantity)}\n\n`);
      body += `ORDER TOTAL: ${money(cartSubtotal())}\n\nPlease confirm availability, pricing, and fulfilment terms.`;
      window.location.href=`mailto:${SALES_EMAIL}?subject=${encodeURIComponent('Order Request - Apex Coating East Africa Ltd')}&body=${encodeURIComponent(body)}`;
    }

